1|// Header for hyp-1-experts-exact hardening, round-2 attempt-7 (builder-1-g).
2|// Builds on attempt-5 (fused single kernel, 512 threads/pair, interleaved
3|// gate/up + parallel block stores) with attempt-6's down-interleave.
4|// One main change vs attempt-6: the second accumulator is ONE
5|// kernel-scope q[32] shared between gate/up and down (see block-0),
6|// so the helpers below are unchanged; their thread float* second
7|// argument now always receives the same storage q.
8|//  - qvm_block: bit-faithful replica of MLX affine_gather_qvm (unchanged
9|//    from attempt-1; kept verbatim, now unused — its per-block arithmetic
10|//    is copied into the two pair helpers).
11|//  - qvm_gate_up_pair: gate and up for the same 32-output block in one
12|//    K loop — unchanged from attempt-4/5.
13|//  - qvm_down_pair: two down 32-output blocks in one K loop — both
14|//    blocks' weight/scale loads issued before either accumulates,
15|//    per-block order unchanged (new in this attempt).
16|//  - qmm_accum: prefill (rows>=60) scalar mimic of affine_gather_qmm_rhs,
17|//    unchanged from attempt-1 (see notes.md).
18|
19|// Decode arithmetic (rows < 60): each lane accumulates its strided K
20|// elements serially in float32, dequantizing on the fly as
21|// x * (scale * q + bias), then a simd_sum tree reduces across lanes.
22|inline void qvm_block(
23|    const device uint* W,
24|    const device bfloat* S,
25|    const device bfloat* B,
26|    const threadgroup bfloat* xv,
27|    uint K,
28|    uint G,
29|    uint Ww,
30|    uint g,
31|    uint wb,
32|    uint lane,
33|    thread float* p) {
34|  for (uint j = 0; j < 32u; ++j) {
35|    p[j] = 0.0f;
36|  }
37|  for (uint k = lane; k < K; k += 32u) {
38|    float x = (float)xv[k];
39|    float scale = (float)S[k * G + g];
40|    float bias = (float)B[k * G + g];
41|    float s0 = scale;
42|    float s1 = scale / 16.0f;
43|    ulong row = (ulong)k * (ulong)Ww + (ulong)wb;
44|    uint w4[4];
45|    for (uint j = 0; j < 4u; ++j) {
46|      w4[j] = W[row + j];
47|    }
48|    for (uint i = 0; i < 16u; ++i) {
49|      uint by = (w4[i >> 2] >> ((i & 3u) * 8u)) & 0xffu;
50|      p[2u * i] += x * (s0 * (float)(by & 0x0fu) + bias);
51|      p[2u * i + 1u] += x * (s1 * (float)(by & 0xf0u) + bias);
52|    }
53|  }
54|#pragma clang loop unroll(full)
55|  for (uint j = 0; j < 32u; ++j) {
56|    p[j] = simd_sum(p[j]);
57|  }
58|}
