1|// Fused combine with contraction-free exact sum: thread-per-output kernel
2|// identical to the starting point (muse-spark/kernels/combine/attempt-1)
3|// except the 4-term sum is evaluated with precise stepwise rounding so no
4|// mul+add is FP-contracted into an FMA. Grid is (rows*768, 1, 1),
5|// threadgroup (256, 1, 1), no threadgroup memory.
6|//
7|// Reference (slots.py:51-52): (y * weights[..., None]).sum(axis=-2)
8|//   .astype(bf16) + shared. y is [rows,4,768] bf16 row-contiguous, weights
9|//   [rows,4] f32, shared [rows,768] bf16, out [rows,768] bf16.
10|//
11|// Exact sequence reproduced (hyp-3-combine-exact Boundary):
12|//   1. cast y bf16->f32 exactly;
13|//   2. each product p_j = float(y_j) * weights_j rounded once to f32;
14|//   3. fold ((p0+p1)+p2)+p3 with a rounding after every add;
15|//   4. round the sum once to bfloat16;
16|//   5. add shared in bfloat16 with a single rounding.
17|// Steps 2-3 are forced by volatile thread variables: each volatile store
18|// materialises its f32 value, so the compiler cannot keep a product
19|// unrounded into the next add (explicit rounding barriers, fma-free).
20|// The Meta qualifier spelling `precise float` does not compile under
21|// MLX's header (metal::precise is a function namespace there), so
22|// volatile stepwise barriers provide the precise semantics. The final
23|// bfloat(acc) + shared line is verbatim from the starting point.
24|
25|uint idx = thread_position_in_grid.x;
26|uint row = idx / 768u;
27|uint d = idx - row * 768u;
28|
29|uint wbase = row * 4u;
30|uint ybase = row * 3072u + d; // 4*768
31|uint sbase = row * 768u + d;
32|
33|volatile float p0 = float(y[ybase]) * weights[wbase];
34|volatile float p1 = float(y[ybase + 768u]) * weights[wbase + 1u];
35|volatile float p2 = float(y[ybase + 1536u]) * weights[wbase + 2u];
36|volatile float p3 = float(y[ybase + 2304u]) * weights[wbase + 3u];
37|volatile float s01 = p0 + p1;
38|volatile float s012 = s01 + p2;
39|volatile float acc = s012 + p3;
40|
41|out[sbase] = bfloat(acc) + shared[sbase];

