30|// Stage shared[row]: 768 bf16 = 192 uint64, one vectorized load per thread.
31|{
32|  const device uint64_t* sp = (const device uint64_t*)(shared + row * 768u);
33|  uint64_t q = sp[tid];
34|  uint base = tid * 4u;
35|  shsh[base + 0u] = as_type<float>((uint(q & 0xFFFFull)) << 16u);
36|  shsh[base + 1u] = as_type<float>((uint((q >> 16) & 0xFFFFull)) << 16u);
37|  shsh[base + 2u] = as_type<float>((uint((q >> 32) & 0xFFFFull)) << 16u);
38|  shsh[base + 3u] = as_type<float>((uint((q >> 48) & 0xFFFFull)) << 16u);
