// every block's bits are identical to two sequential qvm_block calls.
inline void qvm_down_pair(
    const device uint* W,
    const device bfloat* S,
    const device bfloat* B,
    const threadgroup bfloat* xv,
    uint K,
    uint G,
    uint Ww,
