201|// multiply, as QuantizedBlockLoader/dequantize does into Ws:
202|//   w = bfloat(float(scale) * q + float(bias))
203|// (MLX writes the odd nibble as (s/16)*(byte&0xf0)+b; that is the same
204|// float value: scaling by powers of two is exact and s*q is exact in
205|// float32 for 4-bit q, so both forms round identically.)
206|inline float qmm_accum(
207|    const device uint* W,
208|    const device bfloat* S,
209|    const device bfloat* B,
210|    const threadgroup bfloat* xv,
211|    uint K,
212|    uint G,
213|    uint Ww,
214|    uint g,
215|    uint wb,
216|    uint lane) {
217|  uint word = wb + (lane >> 3u);
218|  uint shift = (lane & 7u) * 4u;
219|  float acc = 0.0f;
220|  for (uint tile = 0u; tile < K; tile += 32u) {
221|    for (uint kk = 0u; kk < 32u; ++kk) {
222|      uint k = tile + kk;
223|      uint w = W[(ulong)k * (ulong)Ww + (ulong)word];
224|      uint q = (w >> shift) & 0xfu;
225|      float wq = (float)S[k * G + g] * (float)q + (float)B[k * G + g];
226|      acc += (float)xv[k] * (float)(bfloat)wq;
227|    }
228|  }
229|  return acc;
