// One 8-wide MMA step over Xs/Ws tiles into C[4][2] (sg's 8 rows x 32 cols).
inline void mma_step(
    const threadgroup bfloat *Xs,
    const threadgroup bfloat *Ws,
    uint sg,
    uint fm,
    uint fn,
    uint kk,
    thread float (*C)[2]) {
  uint a_row = sg * 8u + fm;
